-- =====================================================================
-- Inicialización de catalog_record y catalog_record_value
-- Jerarquía CRITERIO_PRIORIZACION > SUBCRITERIO_PRIORIZACION > ESCALA_PRIORIZACION
-- Origen : catalogos__inicializacion.json, grupo code = 'CRITERIO_PRIORIZACION'
--          140 items: 4 criterios (nivel 1), 17 subcriterios (nivel 2),
--          119 opciones de escala (nivel 3)
-- Dialecto: SQL ANSI (SQL:2003)
-- ---------------------------------------------------------------------
-- Prerrequisitos
--   * catalog contiene los code 'CRITERIO_PRIORIZACION', 'SUBCRITERIO_PRIORIZACION', 'ESCALA_PRIORIZACION', encadenados por parent_id
--     (SUBCRITERIO -> CRITERIO, ESCALA -> SUBCRITERIO; Regla 23).
--   * catalog_field define:
--       CRITERIO_PRIORIZACION    : 'codigo', 'nombre', 'ponderacion'
--       SUBCRITERIO_PRIORIZACION : 'codigo', 'nombre', 'ponderacion'
--       ESCALA_PRIORIZACION      : 'codigo', 'nombre'
--
-- Valores cargados
--   CRITERIO    : codigo, nombre, ponderacion (atributos_extra.ponderacion_criterio)
--   SUBCRITERIO : codigo, nombre, ponderacion (atributos_extra.ponderacion_subcriterio)
--   ESCALA      : codigo = atributos_extra.valor ('NA', '0'..'5'),
--                 nombre = atributos_extra.descripcion
--   Las ponderaciones son numéricas en el JSON y se guardan como texto ('30').
--
-- Mecánica
--   SQL ANSI no tiene una función portable para leer el último id generado;
--   se usan subconsultas escalares limitadas a los registros de esta carga
--   (id > MAX(id) previo, guardado en tmp_pr_control):
--     * padre de un SUBCRITERIO: el último CRITERIO insertado (los subcriterios
--       siguen a su criterio en el JSON);
--     * padre de una opción de ESCALA: el SUBCRITERIO cargado cuyo valor
--       'codigo' es igual a item_padre_codigo (en el JSON las escalas vienen
--       todas al final, no a continuación de su subcriterio);
--     * valores de cada item: el último registro insertado de su catálogo.
--   Condición: una sola sesión, sin inserciones concurrentes en
--   catalog_record. Se recomienda ejecutarlo dentro de una única transacción.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Paso 1. Tablas temporales
--   tmp_pr_control : MAX(id) de catalog_record antes de la carga.
--   tmp_pr_esperado: pares (catálogo, codigo, codigo del padre) que deben quedar
--                  cargados; se usa en la verificación final (paso 5).
-- ---------------------------------------------------------------------
CREATE LOCAL TEMPORARY TABLE tmp_pr_control (
    max_record_id_previo BIGINT NOT NULL
) ON COMMIT PRESERVE ROWS;

CREATE LOCAL TEMPORARY TABLE tmp_pr_esperado (
    catalog_code   VARCHAR(64)   NOT NULL,
    codigo         VARCHAR(4000) NOT NULL,
    padre_codigo   VARCHAR(4000)
) ON COMMIT PRESERVE ROWS;


-- ---------------------------------------------------------------------
-- Paso 2. Verificación previa — DEBE DEVOLVER 0 FILAS antes de continuar
-- ---------------------------------------------------------------------
SELECT x.code, x.problema
FROM (
    SELECT e.code,
           CASE WHEN c.id  IS NULL THEN 'catálogo inexistente'
                WHEN fc.id IS NULL THEN 'falta campo codigo'
                WHEN fn.id IS NULL THEN 'falta campo nombre'
                WHEN e.code <> 'ESCALA_PRIORIZACION' AND fp.id IS NULL THEN 'falta campo ponderacion'
                WHEN e.code = 'SUBCRITERIO_PRIORIZACION'
                 AND (c.parent_id IS NULL OR c.parent_id <> (SELECT id FROM catalog WHERE code = 'CRITERIO_PRIORIZACION'))
                     THEN 'parent_id no apunta a CRITERIO_PRIORIZACION (Regla 23)'
                WHEN e.code = 'ESCALA_PRIORIZACION'
                 AND (c.parent_id IS NULL OR c.parent_id <> (SELECT id FROM catalog WHERE code = 'SUBCRITERIO_PRIORIZACION'))
                     THEN 'parent_id no apunta a SUBCRITERIO_PRIORIZACION (Regla 23)'
           END AS problema
    FROM (VALUES ('CRITERIO_PRIORIZACION'), ('SUBCRITERIO_PRIORIZACION'), ('ESCALA_PRIORIZACION')) AS e (code)
    LEFT JOIN catalog c        ON c.code = e.code
    LEFT JOIN catalog_field fc ON fc.catalog_id = c.id AND fc.name = 'codigo'
    LEFT JOIN catalog_field fn ON fn.catalog_id = c.id AND fn.name = 'nombre'
    LEFT JOIN catalog_field fp ON fp.catalog_id = c.id AND fp.name = 'ponderacion'
) x
WHERE x.problema IS NOT NULL;

-- ---------------------------------------------------------------------
-- Paso 3. Punto de partida de la identidad
-- ---------------------------------------------------------------------
SELECT COALESCE(MAX(id), 0) FROM catalog_record;

-- ---------------------------------------------------------------------
-- Paso 4. Carga, item por item, en el orden del JSON
-- ---------------------------------------------------------------------

-- =============================== CRITERIO: CRITERIO 1 — MADUREZ TÉCNICA Y CUMPLIMIENTO REGULATORIO
-- SUBCRITERIO: SUB1.1 Avance en estudios de preinversión
-- SUBCRITERIO: SUB1.2 Análisis de alternativas y justificación
-- SUBCRITERIO: SUB1.3 Metas físicas e indicadores
-- SUBCRITERIO: SUB1.4 Diseños y especificaciones técnicas
-- SUBCRITERIO: SUB1.5 Cronograma, ruta crítica y riesgos

-- =============================== CRITERIO: CRITERIO 2 — RENTABILIDAD SOCIAL O VALOR PÚBLICO
-- SUBCRITERIO: SUB2.1 Tipo y solidez del indicador socioeconómico
-- SUBCRITERIO: SUB2.2 Resultado del indicador de evaluación
-- SUBCRITERIO: SUB2.3 Magnitud y valor económico-social de los beneficios
-- SUBCRITERIO: SUB2.4 Claridad del vínculo problema-solución-beneficio

-- =============================== CRITERIO: CRITERIO 3 — IMPACTO TERRITORIAL Y CIERRE DE BRECHAS
-- SUBCRITERIO: SUB3.1 Rezago relativo del territorio beneficiado
-- SUBCRITERIO: SUB3.2 Profundidad de la brecha que el proyecto contribuye a cerrar
-- SUBCRITERIO: SUB3.3 Beneficio sobre población en condición de vulnerabilidad
-- SUBCRITERIO: SUB3.4 Cobertura territorial de la intervención
-- SUBCRITERIO: SUB3.5 Complementariedad y efectos de red con otras inversiones

-- =============================== CRITERIO: CRITERIO 4 — SOSTENIBILIDAD FISCAL Y FINANCIERA PARA LA ETAPA DE EJECUCIÓN
-- SUBCRITERIO: SUB4.1 Compatibilidad del costo total y perfil multianual con la programación
-- SUBCRITERIO: SUB4.2 Costos de operación y mantenimiento (O&M)
-- SUBCRITERIO: SUB4.3 Certidumbre y estructura de la fuente de financiamiento

