-- ---------------------------------------------------------------------
-- Paso 5. Verificación posterior
-- ---------------------------------------------------------------------
-- 5.1 Conteos. Esperado: CRITERIO_PRIORIZACION 4/12, SUBCRITERIO_PRIORIZACION 17/51, ESCALA_PRIORIZACION 119/238
SELECT c.code,
       COUNT(DISTINCT r.id) AS registros,
       COUNT(v.id)          AS valores
FROM catalog c
JOIN catalog_record r            ON r.catalog_id = c.id
LEFT JOIN catalog_record_value v ON v.record_id = r.id
WHERE c.code IN ('CRITERIO_PRIORIZACION', 'SUBCRITERIO_PRIORIZACION', 'ESCALA_PRIORIZACION')
  AND r.id > (SELECT max_record_id_previo FROM tmp_pr_control)
GROUP BY c.code;

-- 5.2 Jerarquía: pares (catálogo, codigo, codigo del padre) esperados frente
--     a los cargados, en ambos sentidos. DEBE DEVOLVER 0 FILAS.
--     (En ESCALA el codigo 'NA', '0'..'5' se repite entre subcriterios; por
--      eso se compara el par completo y no el codigo aislado.)
SELECT 'falta o padre incorrecto' AS problema, catalog_code, codigo, padre_codigo
FROM (
    SELECT catalog_code, codigo, padre_codigo FROM tmp_pr_esperado
    EXCEPT
    SELECT c.code, vh.valor, vp.valor
    FROM catalog_record rh
    JOIN catalog c              ON c.id = rh.catalog_id AND c.code IN ('CRITERIO_PRIORIZACION', 'SUBCRITERIO_PRIORIZACION', 'ESCALA_PRIORIZACION')
    JOIN catalog_record_value vh ON vh.record_id = rh.id
    JOIN catalog_field fh        ON fh.id = vh.field_id AND fh.name = 'codigo'
    LEFT JOIN catalog_record_value vp ON vp.record_id = rh.parent_record_id
                                     AND vp.field_id IN (SELECT id FROM catalog_field WHERE name = 'codigo')
    WHERE rh.id > (SELECT max_record_id_previo FROM tmp_pr_control)
) faltantes
UNION ALL
SELECT 'sobrante', catalog_code, codigo, padre_codigo
FROM (
    SELECT c.code AS catalog_code, vh.valor AS codigo, vp.valor AS padre_codigo
    FROM catalog_record rh
    JOIN catalog c              ON c.id = rh.catalog_id AND c.code IN ('CRITERIO_PRIORIZACION', 'SUBCRITERIO_PRIORIZACION', 'ESCALA_PRIORIZACION')
    JOIN catalog_record_value vh ON vh.record_id = rh.id
    JOIN catalog_field fh        ON fh.id = vh.field_id AND fh.name = 'codigo'
    LEFT JOIN catalog_record_value vp ON vp.record_id = rh.parent_record_id
                                     AND vp.field_id IN (SELECT id FROM catalog_field WHERE name = 'codigo')
    WHERE rh.id > (SELECT max_record_id_previo FROM tmp_pr_control)
    EXCEPT
    SELECT catalog_code, codigo, padre_codigo FROM tmp_pr_esperado
) sobrantes;

-- ---------------------------------------------------------------------
-- Paso 6. Limpieza
-- ---------------------------------------------------------------------
DROP TABLE tmp_pr_esperado;
DROP TABLE tmp_pr_control;
